      "riskTaking": 0.2,
      "processFocus": 0.05,
      "resilience": 0.1,
      "innovation": 0.3,
      "stakeholderManagement": 0.15,
      "executionSpeed": 0.2
    },
    "reasoning": "Digital transformation demands innovation leadership and calculated risk-taking to drive change."
  },
  "automotive_continuity": {
    "weights": {
      "riskTaking": 0.05,
      "processFocus": 0.3,
