// Gather all agent outputs
const prepData = $('Prepare Data').first().json;
const jdOutput = $('JD Context Agent').first().json.output;
const cvOutput = $('CV Scoring Agent').first().json.output;
const decisionOutput = $('Decision Intelligence Agent').first().json.output;
const candidatePool = prepData.candidate_pool;

// Map n8n scenario keys (underscore) → frontend keys (hyphen)
const keyMap = {
  'automotive_continuity': 'automotive-continuity',
  'transformation': 'transformation',
  'supply_chain_crisis': 'supply-chain-crisis'
};

// Build frontend-compatible Candidate[] array
const candidates = cvOutput.scored_candidates.map(scored => {
  const base = candidatePool.find(c => c.id === scored.id) || {};

  const fitScores = {};
  const riskScore = {};
  const reasoning = {};

  for (const [nKey, feKey] of Object.entries(keyMap)) {
    fitScores[feKey] = scored.fitScores?.[nKey] ?? 50;
    riskScore[feKey] = scored.riskScores?.[nKey] ?? 5;
    reasoning[feKey] = scored.reasoning?.[nKey] ?? '';
  }

  return {
    id: scored.id,
    name: scored.name,
    currentRole: base.current_role || '',
    company: base.company || 'BMW Group',
    yearsExperience: base.experience_years || 10,
    avatarInitials: base.avatar_initials || scored.name.split(' ').map(w => w[0]).join(''),
    traits: scored.traits,
    fitScores,
    timeToHire: base.time_to_hire || 30,
    costToHire: base.cost_to_hire || 5,
    riskScore,
    reasoning,
    isNew: base.is_new || false,
    bio: base.bio || null
  };
});

// Build decisions per scenario (frontend-friendly keys)
const decisions = {};
for (const [nKey, feKey] of Object.entries(keyMap)) {
  const d = decisionOutput[nKey] || {};
  decisions[feKey] = {
    recommended_candidate: d.recommended_candidate || 'Unknown',
    rationale: d.rationale || '',
    trade_off: d.trade_off || '',
    skill_gap_analysis: d.skill_gap_analysis || '',
    risks: Array.isArray(d.risks) ? d.risks : [],
    confidence_level: d.confidence_level || 'Medium',
    alternatives: Array.isArray(d.alternatives) ? d.alternatives : []
  };
}

// Build weights per scenario (frontend-friendly keys)
const weights = {};
for (const [nKey, feKey] of Object.entries(keyMap)) {
  weights[feKey] = jdOutput[nKey]?.weights || {};
}

// Return the Master JSON
return [{
  json: {
    status: "success",
    data: {
      candidates: candidates,
      decisions: decisions,
      weights: weights
    }
  }
}];
